(function(){
'use strict';
const $=id=>document.getElementById(id),api=()=>window.CAGE_BACKEND,esc=escapeHtml;
let prefs,routeData;
const zone=()=>Intl.DateTimeFormat().resolvedOptions().timeZone||'Africa/Blantyre';
const defaults=()=>({delivery:'immediate',daily_digest:true,reminder_email:false,time_zone:zone(),workdays:[1,2,3,4,5]});
const button=document.createElement('button');button.className='secondary-button';button.textContent='Email preferences';button.onclick=()=>openPreferences();document.querySelector('[data-view-panel="notifications"] .section-intro').append(button);
document.body.insertAdjacentHTML('beforeend',`<dialog class="app-dialog" id="email-preferences-dialog"><form id="email-preferences-form" data-personal-readonly><div class="dialog-heading"><h2>Email preferences</h2><button type="button" data-close-email="email-preferences-dialog" aria-label="Close">×</button></div><label class="field"><span>Routine work updates</span><select name="delivery"><option value="immediate">Email promptly</option><option value="digest">Combine in a daily digest</option><option value="inapp">In-app only</option></select></label><label class="field"><span><input type="checkbox" name="daily_digest"> Include my planned work, deadlines and equipment in the 07:00 digest</span></label><label class="field"><span><input type="checkbox" name="reminder_email"> Also email my personal reminders</span></label><label class="field"><span>Time zone</span><input name="time_zone" required list="email-time-zones"><datalist id="email-time-zones"></datalist><button type="button" id="email-device-zone">Use this device’s time zone</button></label><fieldset><legend>Working days</legend>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label style="display:inline-block;margin:8px"><input type="checkbox" name="workday" value="${i}"> ${d}</label>`).join('')}</fieldset><p>Mentions wait 15 minutes and are skipped when read. Assignments are combined for two minutes. Reminders follow the advance time you choose. Empty digests are skipped.</p><p>Account access emails and client document sending failures are kept separate from routine preferences.</p><p id="email-preferences-status" role="status"></p><div class="dialog-actions"><button class="primary-button">Save preferences</button></div></form></dialog>
<dialog class="app-dialog" id="email-routing-dialog"><form id="email-routing-form"><div class="dialog-heading"><h2>Staff email routing</h2><button type="button" data-close-email="email-routing-dialog" aria-label="Close">×</button></div><p>Only staff with access to the relevant module receive its emails.</p><fieldset><legend>Approval recipients</legend><p>Leave empty to notify all active administrators and managers.</p><div id="email-approvers"></div></fieldset><fieldset><legend>Business development digest</legend><p>Choose who receives strong opportunity matches. Empty means nobody.</p><div id="email-bd"></div></fieldset><p id="email-routing-status" role="status"></p><button class="primary-button">Save routing</button><h3>Recent email submissions</h3><p>“Sent” means accepted by the email provider. It does not confirm inbox delivery.</p><div id="email-history"></div></form></dialog>`);
const zones=typeof Intl.supportedValuesOf==='function'?Intl.supportedValuesOf('timeZone'):['Africa/Blantyre','Africa/Johannesburg','Europe/London','UTC'];$('email-time-zones').innerHTML=zones.map(z=>`<option value="${esc(z)}">`).join('');
const admin=document.createElement('button');admin.className='secondary-button';admin.id='staff-email-routing';admin.textContent='Staff email routing & history';admin.hidden=true;admin.onclick=()=>openRouting();document.querySelector('[data-view-panel="settings"]').prepend(admin);
async function openPreferences(){const f=$('email-preferences-form');$('email-preferences-status').textContent='Loading…';f.querySelector('button.primary-button').disabled=true;$('email-preferences-dialog').showModal();try{prefs={...defaults(),...await api().emailPreferences()};for(const k of ['delivery','time_zone'])f.elements[k].value=prefs[k];for(const k of ['daily_digest','reminder_email'])f.elements[k].checked=prefs[k];f.querySelectorAll('[name="workday"]').forEach(x=>x.checked=prefs.workdays.includes(Number(x.value)));$('email-preferences-status').textContent='';f.querySelector('button.primary-button').disabled=false;}catch(e){$('email-preferences-status').textContent='Could not load preferences: '+e.message;}}
$('email-device-zone').onclick=()=>$('email-preferences-form').elements.time_zone.value=zone();
$('email-preferences-form').elements.delivery.onchange=e=>{if(e.target.value==='inapp')$('email-preferences-form').elements.daily_digest.checked=false;};
$('email-preferences-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=e.submitter;b.disabled=true;try{const days=[...f.querySelectorAll('[name="workday"]:checked')].map(x=>Number(x.value));if(!days.length)throw new Error('Choose at least one working day.');new Intl.DateTimeFormat(undefined,{timeZone:f.elements.time_zone.value.trim()});await api().saveEmailPreferences({delivery:f.elements.delivery.value,daily_digest:f.elements.daily_digest.checked,reminder_email:f.elements.reminder_email.checked,time_zone:f.elements.time_zone.value.trim(),workdays:days});$('email-preferences-status').textContent='Preferences saved.';}catch(e){$('email-preferences-status').textContent=e.message;}finally{b.disabled=false;}};
async function openRouting(){if(api().currentProfile()?.role!=='admin')return;$('email-routing-dialog').showModal();$('email-routing-status').textContent='Loading…';$('email-routing-form').querySelector('.primary-button').disabled=true;try{routeData=await api().emailRouting();for(const [id,key,users] of [['email-approvers','approval_users',routeData.users.filter(u=>['admin','manager'].includes(u.role))],['email-bd','opportunity_users',routeData.users]])$(id).innerHTML=users.map(u=>`<label style="display:block;padding:8px"><input type="checkbox" name="${key}" value="${u.id}" ${(routeData.routing[key]||[]).includes(u.id)?'checked':''}> ${esc(u.full_name)}</label>`).join('');$('email-history').innerHTML=routeData.history.map(h=>`<div class="personal-row"><div><strong>${esc(h.subject)}</strong><small>${esc(routeData.users.find(u=>u.id===h.user_id)?.full_name||'Former staff')} · ${esc(new Date(h.created_at).toLocaleString())}</small><small>${esc(h.error||'')}</small></div><span>${esc(h.status)}</span></div>`).join('')||'<p>No staff emails have been queued yet.</p>';$('email-routing-status').textContent='';$('email-routing-form').querySelector('.primary-button').disabled=false;}catch(e){$('email-routing-status').textContent=e.message;}}
$('email-routing-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api().saveEmailRouting(Object.fromEntries(['approval_users','opportunity_users'].map(k=>[k,[...e.currentTarget.querySelectorAll(`[name="${k}"]:checked`)].map(x=>x.value)])));$('email-routing-status').textContent='Routing saved.';}catch(e){$('email-routing-status').textContent=e.message;}finally{b.disabled=false;}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-close-email]');if(b)$(b.dataset.closeEmail).close();});
// Save read state only while the conversation is actually visible.
async function readVisibleChat(){if(api().currentProfile()&&!document.hidden&&activeView==='chat'&&activeChatThread)try{await api().readChatNotifications(activeChatThread);await window.CAGE_PERSONAL?.refresh?.();renderChat();renderDashboard();}catch(e){console.warn('Chat read state could not sync');}}
const select=selectChatThread;selectChatThread=function(id){const result=select(id);readVisibleChat();return result;};
let interval;window.addEventListener('cage:session-ready',()=>{admin.hidden=api().currentProfile()?.role!=='admin';api().emailPreferences().then(p=>{if(!p)return api().saveEmailPreferences(defaults());}).catch(()=>{});clearInterval(interval);interval=setInterval(readVisibleChat,15000);openEmailLink();});document.addEventListener('visibilitychange',readVisibleChat);
async function openEmailLink(){const params=new URLSearchParams(location.search),view=params.get('view'),id=params.get('record');if(!view||!viewMeta[view])return;if(api().moduleLevel(view)==='none'){setView('notifications');showToast('Your access to this module has changed.');return;}setView(view);try{
 if(view==='tasks'&&state.tasks.some(t=>t.id===id))openTask(id);
 else if(view==='projects'&&state.projects.some(t=>t.id===id))openProject(id);
 else if(view==='requests'&&state.requests.some(t=>t.id===id))openRequest(id);
 else if(view==='chat'&&threadById(id))selectChatThread(id);
 else if(view==='finance'){const type=state.quotes.some(t=>t.id===id)?'quote':state.invoices.some(t=>t.id===id)?'invoice':null;if(type)openSendDocument(type,id);}
 else if(view==='assets'){const a=assetById(id);if(a){$('asset-search').value=a.tag;assetFilter='all';renderAssets();}}
 else if(view==='approvals'){document.querySelector(`[data-decide-approval="${CSS.escape(id||'')}"]`)?.closest('article')?.scrollIntoView({block:'center'});}
 else if(view==='mywork'&&id){document.querySelector(`[data-reminder-row="${CSS.escape(id)}"]`)?.scrollIntoView({block:'center'});}
 }catch(e){showToast('Open the relevant record from this page.');}}
// A separate explicit request avoids escalating every blocked task automatically.
const help=document.createElement('button');help.type='button';help.className='secondary-button';help.textContent='Ask project lead for help';help.onclick=async()=>{help.disabled=true;try{await api().requestTaskHelp($('planner-status-form').elements.taskId.value);$('planner-update-error').textContent='Help requested. Your project lead will be notified according to their email preferences.';}catch(e){$('planner-update-error').textContent=e.message+'. Save the blocked status and reason first.';}finally{help.disabled=false;}};$('planner-status-form').querySelector('.dialog-actions').prepend(help);
})();
